const usuario = (0, _user.createUser)({
  nome: ''
});
cy.request({
  method: 'POST',
  url: `${Cypress.expose('url_serve_rest')}/usuarios`,
  body: usuario,
  failOnStatusCode: false
}).then(response => {
  expect(response.status).to.eq(400);
  expect(response.body.nome).to.eq('nome não pode ficar em branco');
});

